import React, { useEffect, useState } from "react";
import { useLocation } from "react-router-dom";
import "./clippreview.css";

function ClipPreview() {
    const location = useLocation();
    const { clipPaths = [], videoURL = null } = location.state || {};
    const [error, setError] = useState(null);
    const [processedClipPaths, setProcessedClipPaths] = useState([]);
    const [selectedClips, setSelectedClips] = useState([]);
    const [selectedFeatures, setSelectedFeatures] = useState([]);
useEffect(() => {
    // Log the received clipPaths
    console.log("Received clipPaths:", clipPaths);

    // Check for clip paths validity
    if (!clipPaths || clipPaths.length === 0) {
        setError("No clips found to display.");
    } else {
        // Transform the clipPaths to URLs
        const baseUrl = "http://127.0.0.1:8000/media/";
        const extractedPaths = clipPaths.map((clipPath) => {
            const relativePath = clipPath.replace(/^.*backend\/media\//, ""); // Extract relative path from the full path
            return `${baseUrl}${relativePath}`;
        });

        console.log("Transformed clipPaths:", extractedPaths);

        if (extractedPaths.length === 0) {
            setError("No valid video paths found.");
        } else {
            setProcessedClipPaths(extractedPaths);
        }
    }
}, [clipPaths]);
    const handleClipSelection = (clipPath) => {
        setSelectedClips((prev) =>
            prev.includes(clipPath)
                ? prev.filter((path) => path !== clipPath)
                : [...prev, clipPath]
        );
    };

    const handleFeatureToggle = (feature) => {
        setSelectedFeatures((prevFeatures) =>
            prevFeatures.includes(feature)
                ? prevFeatures.filter((f) => f !== feature)
                : [...prevFeatures, feature]
        );
    };

    const handleOptimize = () => {
        if (selectedClips.length === 0) {
            alert("Please select at least one clip to optimize.");
            return;
        }
        if (selectedFeatures.length === 0) {
            alert("Please select at least one feature to apply.");
            return;
        }

        console.log("Optimizing the following clips:", selectedClips);
        console.log("Selected features:", selectedFeatures);

        // Handle the optimization logic here (e.g., API call to process clips)
        alert("Optimization started!");
    };

    return (
        <div className="clipping-app">
            {/* Header Section */}
            <header className="header">
                <h1 className="logo">
                    <span className="bold">Channel-</span>
                    <span className="highlight">IQ</span>
                </h1>
                <nav className="nav">
                    <a href="#clipper">Clipper</a>
                    <a href="#seo">SEO</a>
                    <a href="#thumbnail">Thumbnail</a>
                    <a href="#pricing">Pricing</a>
                    <button className="sign-in">Sign in</button>
                    <button className="sign-up">Sign up</button>
                </nav>
            </header>

            {/* Main Content Section */}
            <main className="main-content">
                <section className="clipper-section">
                    <button className="clipper-btn">Clipper</button>

                    {/* Viral Clips Section */}
                    <div className="viral-clips">
    <h3>Your Viral Clips</h3>
    <div className="clip-thumbnails">
        {error ? (
            <p className="error-message">{error}</p>
        ) : (
            processedClipPaths.map((clipPath, index) => (
                <div key={index} className="clip-container">
                    {/* Video Element */}
                    <video
                        src={clipPath} // Dynamic video path
                        controls
                        className="clip-thumbnail"
                    />
                    {/* Checkbox for Selection */}
                    <label className="clip-checkbox">
                        <input
                            type="checkbox"
                            onChange={() => handleClipSelection(clipPath)} // Handle selection
                            checked={selectedClips.includes(clipPath)} // Check if selected
                        />
                        Select Clip {index + 1} {/* Dynamic Label */}
                    </label>
                </div>
            ))
        )}
    </div>
</div>
                    {/* Features Selection Section */}
                    <div className="features">
                        <h3>Select Features to Apply:</h3>
                        {[
                            "Noise Reduction",
                            "Video Quality",
                            "SEO",
                            "Captions"
                        ].map((feature) => (
                            <button
                                key={feature}
                                className={`feature-btn ${
                                    selectedFeatures.includes(feature) ? "active" : ""
                                }`}
                                onClick={() => handleFeatureToggle(feature)}
                            >
                                {feature}
                            </button>
                        ))}
                    </div>

                    <div className="optimize-btn">
                        <button
                            onClick={handleOptimize}
                            disabled={selectedClips.length === 0 || selectedFeatures.length === 0}
                        >
                            Optimize
                        </button>
                    </div>
                </section>
            </main>
        </div>
    );
}

export default ClipPreview;
